// frontend/src/components/TableView.js
import React, { useMemo } from "react";

export default function TableView({ rows = [] }) {
  // ✔ ALWAYS call hooks at the top level (NOT conditionally)
  const cols = useMemo(() => {
    if (!rows || rows.length === 0) return [];
    return Object.keys(rows[0]);
  }, [rows]);

  // ✔ Safe: this is a simple conditional render (NO hooks below)
  if (!rows || rows.length === 0) {
    return (
      <div className="text-muted small">
        No matching rows. Try a different area or upload data.
      </div>
    );
  }

  return (
    <div style={{ maxHeight: 300, overflow: "auto" }}>
      <table className="table table-sm table-hover">
        <thead className="table-light sticky-top">
          <tr>
            {cols.map((c) => (
              <th key={c} className="text-nowrap">{c}</th>
            ))}
          </tr>
        </thead>

        <tbody>
          {rows.map((r, i) => (
            <tr key={i}>
              {cols.map((c) => (
                <td key={c} className="text-nowrap">
                  {String(r[c] ?? "")}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
